INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO,PARAMETRO,DESCRIZIONE) VALUES('PROTOCOLLO_ATTIVO','CLASSIFICADEFAULT_BO','E'' la classifica di default che viene recuperata nelle maschere di protocollazione quando non ne viene recuperata nessun''altra(ad esempio tramite la configurazione dell''albero degli interventi). Usato ad esempio per il Pannello Gestione PEC che non può recuperare la configurazione dall''intervento');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'URL', 'Inserire qui l''url dove raggiungere il web service sicraweb, questo web service espone le funzionalità di registrazione protocollo e lettura protocollo. Sono stati forniti degli ambienti di test sia da Maggioli: http://www.cedaf.it/client/services/ProWSApi?wsdl, che da studio k: http://www.studiok.it:9091/ws_sici/ProWSApi.asmx?wsdl');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il valore del codice dell''amministrazione dell''ente a cui si intende protocollare, questo tipo di dato è obbligatorio e deve essere fornito dall''amministratore del sistema di protocollo, non ha infatti niente a che vedere con le amministrazioni di del Backoffice.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'CODICEAOO', 'Codice IPA dell’AOO mittente del protocollo in uscita, ovvero dell’ente stesso.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'USA_MONO_MITTDEST', 'Indica se deve rispettare il vincolo presenta anche sul protocollo docarea e relativo al fatto che non può inserire più di un mittente / destinatario nella registrazione di un protocollo. Valorizzando questo parametro a 1 allora il sistema inserirà solamente il primo mittente / destinatario nell''elemento Mittente o Destinatario altrimenti inserirà tutti i mittenti / destinatari dentro l''array dell''elemento MittentiMulti e DestinataroMulti.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'INVIA_SEGNATURA', 'Se valorizzato a 1 consente, in fase di protocollazione istanza o movimento da backoffice, di allegare il file di profilazione (segnatura.xml) che sarebbe il file che viene inviato al web service per eseguire la protocollazione. Questa funzionalità viene usata nel momento in cui non sia presente nessun allegato da inviare al protocollo e solo se questo parametro è valorizzato a 1.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SICRAWEB', 'CONNECTIONSTRING', 'E'' un parametro che deve essere fornito dagli amministratori del protocollo in collaborazione con il fornitore, riguarda l''identificativo delle credenziali di connessione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEB', 'FTP_PATH_ALLEGATI', 'Percorso cartella FTP del server dedicato. Lunghezza massima 256 caratteri. Parametro obbligatorio. Inserire qui il path ftp che serve come appoggio per inserire i files allegati ad uno specifico protocollo. Durante la protocollazione infatti, se sono presenti dei files, questi vengono appoggiati sul percorso indicato in questo parametro, per poi essere recuperati dal web service stesso durante l''operazione di inserimento allegato, deve essere quindi il client del protocollo a fare upload dei file su questo percorso');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEB', 'URLALLEGATI', 'E'' l''URL del web service che serve per invocare la funzionalità di inserimento files ad un determinato protocollo. Questa funzionalità viene invocata solo dopo aver protocollato e serve appunto per allegare file al protocollo restituito.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEB', 'CODICE_CC', 'Indica il codice per conoscenza da utilizzare in fase di protocollazione. Sulla maschera di protocollazione è presente un campo a tendina denominato -Trasmesso per- legato all''anagrafica (Mittente / Destinatario), questo campo viene popolato dai valori presenti nella tabella PROTOCOLLO_MODALITAINVIO, indicando il codice in questo campo, quando l''operatore selezionerà nella tendina -Trasmesso per- il valore con lo stesso codice, l''anagrafica selezionata sarà considerata per conoscenza. Se non valorizzato il destinatario (mittente) del protocollo non sarà mai per conoscenza.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEB', 'NOME_DIR_CONDIVISA', 'Indicare il nome della cartella condivisa sul server di protocollo, il fornitore o il CED del comune deve fornire il nome (solo il nome e non tutto il path) della cartella di appoggio utilizzata dal sistema di protocollo per recuperare i files allegati durante l''inserimento di un protocollo.');
INSERT INTO CLMENU_JAVA (ID,DESCRIZIONE,PAGINA,MENULINK,SOFTWARE,JSP,LAYOUTTESTI,VERTICALIZZAZIONE,SOFTWAREESCLUSI,LINK_STANDARD,TIPO_FUNZIONALITA) VALUES(1012,'Allineamento stradario','stradario/createAllineaStradario.htm?software=TT','7C','TT','JAVA',0,NULL,NULL,'stradario/createAllineaStradario.htm?software=TT','E');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEBTEST', 'Questa verticalizzazione è stata creata per rendere più semplici le operazioni in ambiente di test del protocollo siprweb, l''ambiente di test e produzione di questo tipo di protocollo infatti hanno due wsdl differenti, pertanto necessitano di due componenti differenti. Per chiamare questa verticalizzazione è necessario impostare a PROTOCOLLO_SIPRWEBTEST il parametro TIPO_PROTOCOLLO della verticalizzazione PROTOCOLLO_ATTIVO.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','AMBIENTE','OBSOLETO, NON USARE. Inizialmente si era deciso di usare questo parametro per individuare il tipo di ambiente, i namespace dei web service di test e produzione però erano diversi quindi bisognava creare due componenti diversi o comunque delle soluzioni lunghe e dispendiose, per questo si è deciso di usare solamente le classi dell''ambiente di produzione, pur essendo presenti anche quelle di test; qui la vecchia descrizione del parametro. Indica il tipo di ambiente di protocollo che si intende utilizzare, TEST o PRODUZIONE, prende come valori T = Ambiente di Test, P = Ambiente di Produzione. Se si intende cambiare ambiente, oltre a questo parametro, vanno comunque modificati anche gli altri parametri (URL) presenti in questo modulo. Si è deciso di introdurre questo parametro in quanto i namespace dei wsdl dei webservice sono diversi in base al tipo di ambiente invocato, creando quindi la necessità di creare due classi proxy (una di Test e una di Produzione appunto) per ogni webservice presente in questo tipo di protocollo, il valore presente indicherà al componente, che si occupa della gestione del protocollo, di invocare la classe giusta in base all''esigenza del momento. Ad esempio il namespace presente sul wsdl di test del webservice dei TipiDocumento è - http://SIPrWeb/WebService.nsf/TipoDocService.wsdl - mentre per quello di produzione è - http://sipr/WebService.nsf/TipoDocService.wsdl - IMPORTANTE: questo parametro è obbligatorio, se non valorizzato sarà sollevata un''eccezione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','CODICE_CC','Indica il codice per conoscenza da utilizzare in fase di protocollazione. Sulla maschera di protocollazione è presente un campo a tendina denominato -Trasmesso per- legato all''anagrafica (Mittente / Destinatario), questo campo viene popolato dai valori presenti nella tabella PROTOCOLLO_MODALITAINVIO, indicando il codice in questo campo, quando l''operatore selezionerà nella tendina -Trasmesso per- il valore con lo stesso codice, l''anagrafica selezionata sarà considerata per conoscenza. Se non valorizzato il destinatario (mittente) del protocollo non sarà mai per conoscenza.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','FTP_PATH_ALLEGATI','Percorso cartella FTP del server dedicato. Lunghezza massima 256 caratteri. Parametro obbligatorio. Inserire qui il path ftp che serve come appoggio per inserire i files allegati ad uno specifico protocollo. Durante la protocollazione infatti, se sono presenti dei files, questi vengono appoggiati sul percorso indicato in questo parametro, per poi essere recuperati dal web service stesso durante l''operazione di inserimento allegato, deve essere quindi il client del protocollo a fare upload dei file su questo percorso');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','NOME_DIR_CONDIVISA','Indicare il nome della cartella condivisa sul server di protocollo, il fornitore o il CED del comune deve fornire il nome (solo il nome e non tutto il path) della cartella di appoggio utilizzata dal sistema di protocollo per recuperare i files allegati durante l''inserimento di un protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','URLALLEGATI','E'' l''URL del web service che serve per invocare la funzionalità di inserimento files ad un determinato protocollo. Questa funzionalità viene invocata solo dopo aver protocollato e serve appunto per allegare file al protocollo restituito.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','URLCLASSIFICHE','E'' l''URL per invocare la lista delle classifiche');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','URLLEGGI','E'' l''URL per invocare la lettura di un protocollo');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','URLPROTOCOLLA','E'' l''URL per invocare la richiesta di un protocollo');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','URLTIPIDOCUMENTO','E'' l''URL per invocare la lista dei tipi documento');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','USA_WS_CLASSIFICHE','Indica se per il recupero delle classifiche, sull''albero degli interventi, debba essere usato il metodo messo a disposizione del web service (valore = 1) oppure no (valore 0, vuoto o non presente). E'' stato deciso di inserire questo parametro in quanto recuperare le classifiche da web service potrebbe essere macchinoso rendendo la pagina del dettaglio degli interventi molto lenta se i dati dovessero essere molti. Oltre tutto i dati potrebbero creare una lunga lista difficilmente leggibile dagli utenti. In ultimo, se dovesso essere modificati i codici, questi non sarebbero più direttamente visibili sul campo Classifica nel dettaglio degli interventi in quanto non più presenti nella lista.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIPRWEBTEST','USA_WS_TIPIDOC','Indica se per il recupero delle tipologie di documento, sull''albero degli interventi, debba essere usato il metodo messo a disposizione del web service (valore = 1) oppure no (valore 0, vuoto o non presente). E'' stato deciso di inserire questo parametro in quanto recuperare le tipologie di documento da web service potrebbe essere macchinoso rendendo la pagina del dettaglio degli interventi molto lenta se i dati dovessero essere molti. Oltre tutto i dati potrebbero creare una lunga lista difficilmente leggibile dagli utenti. In ultimo, se dovesso essere modificati i codici');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEBTEST', 'DOMINIO', 'Parametro riguardante il salvataggio dei files allegati, il web service infatti costringe il client a salvare files in una cartella condivisa sul server del protocollo, alla quale vanno indicate le credenziali tra le quali il DOMINIO che va indicato in questo parametro');
