insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_ATTIVO', 'PROXY_ADDRESS', 'Valorizzare questo parametro nel momento il server che ospita VBG esca tramite un proxy, percui sia necessario specificare l''indirizzo per raggiungere il web service, come ad esempio succede sulla server farm di Linea Comune. In questo parametro va quindi specificato l''url del proxy. Precedentemente questo parametro era valorizzato dentro il binding del web service presente dentro il file bindings.config, quindi il sistema andrà a cercare il valore inserito dentro il binding nel caso in cui questo parametro sia assente o non valorizzato. IMPORTANTE: Questo parametro è utilizzabile solo con web service in cui lo stub sia stato creato con WCF altrimenti non è possibile indicare l''url del proxy');
