  INSERT INTO COMUNI(CODICECOMUNE, COMUNE, SIGLAPROVINCIA, PROVINCIA, REGIONE, CF, CODICEISTATREGIONE) VALUES ('C575', 'CESI', 'TR', 'TERNI', 'UMBRIA', 'C575', '10');
insert into verticalizzazionibase(modulo, descrizione) values('PROTOCOLLO_TINN', 'E'' il protocollo gestito dalla ditta Tinn in Abruzzo, in teoria, questo protocollo, dovrebbe essere standard docarea, in realtà non lo è in quanto il fornitore non riesce a gestire gli allegati in modo DIME / MIME passandoli quindi direttamente sulla richiesta soap, i metodi hanno inoltre piccole modifiche rispetto a quanto specificato nei documenti docarea (maiuscole, minuscole, nomi di proprietà diversi....), quindi è stato necessario creare una verticalizzazione e relativi parametri uguali a quelli della verticalizzazione PROTOCOLLO_DOCAREA. In realtà questo tipo di protocollo, da certi punti di vista è molto simile al protocollo halley. I servizi di test TINN sono esposti su http://5.98.16.12:7099, qui si possono fare delle prove');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','OPERATORE','(Obbligatorio) Username di autenticazione al web service del protocollo TINN, è il parametro username che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','URL','(Obbligatorio) End point del web service per invocare i servizi, ad esempio per il protocollo TINN l''ambiente di test è presente su http://5.98.16.12:7099/wsdl/DOCAREAProto?wsdl');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','PASSWORD','Password di autenticazione al web service del protocollo TINN, è il parametro password che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','CODICEENTE','Codice Ente, questo parametro va ad aggiungersi a username e password e serve per l''autenticazione al web service del protocollo TINN, è il parametro codiceente che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','INVIA_ALL_MOV_AVVIO','(Facoltativo) Se valorizzato a 1 va a cercare in automatico, solamente durante la protocollazione da istanza, gli allegati caricati nel movimento di avvio dell''istanza stessa, se esistono questi vengono inviati al protocollo TINN.Se valorizzato con valore diverso da 1 o non valorizzato la funzionalità appena descritta non sarà svolta.');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','INVIA_SEGNATURA','(Facoltativo) Se valorizzato a 1 consente, in fase di protocollazione istanza o movimento da backoffice, di inviare il file segnatura.xml che sarebbe il file che viene inviato al web service per eseguire la protocollazione; se valorizzato a 0 o non valorizzato non esegue nessuna funzionalità.');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','CODICE_AOO','(Facoltativo) E'' il codice dell''Area Organizzativa Omogenea, va fornito dagli amministratori del protocollo. In precedenza veniva passato un parametro fisso con valore = ''AOO'' è stato modificato in quanto in alcuni casi (ad esempio Piacenza e Asp Roma) veniva richiesto un valore diverso. Sulle specifiche TINN (che sono le stesse docarea) viene descritto come: viene inizializzato con un valore che identifica l''ambito dell''applicazione.Ad esempio questo codice potrebbe essere utilizzato,per individuare i messaggi provenienti dal portale.Ovviamente si puo’ scegliere come nel caso a) di usare una codifica del tipo P_X dove X e’ il nome dell’applicazione chiamante.Questo valore viene inserito nel file segnatura.xml dentro Intestazione-->Identificatore-->CodiceAOO e dentro Intestazione -->Classifica -->CodiceAOO Se non valorizzato il parametro prenderà il valore di AOO');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','TIPO_DOCUMENTO_ALLEGATO','(Facoltativo) Specificare il valore del tipo documento allegato ossia quei documenti allegati al protocollo escluso quello principale. Se non valorizzato prenderà il valore = ''Allegato'' che era il valore fisso che veniva passato in precedenza. Viene valorizzato nel file segnatura.xml dentro Intestazione --> Descrizione --> Documento --> TipoDocumento successivamente a quello principale.');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','TIPO_DOCUMENTO_PRINCIPALE','(Facoltativo) Specificare il valore del tipo documento principale. ossia quel documento principale o di richiesta del protocollo. Se non valorizzato prenderà il valore = ''Principale'' che era il valore fisso che veniva passato in precedenza. E'' stato parametrizzato perchè a Piacenza viene richiesto un valore specifico che è ''TRAS''. Viene valorizzato nel file segnatura.xml dentro Intestazione --> Descrizione --> Documento --> TipoDocumento');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','APPLICATIVO_PROTOCOLLO','(Facoltativo) Indica il nome dell''applicativo del protocollo, questa voce sarà inserita dentro il file segnatura.xml dentro l''attributo -nome- di <ApplicativoProtocollo/>. NB. Se lasciato vuoto o non attivato prenderà il valore inserito dentro il parametro CODICEENTE');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','UO','(Facoltativo) Indica l''ufficio di smistamento del protocollo TINN, questa voce sarà inserita dentro il file segnatura.xml dentro il nodo <ApplicativoProtocollo> valorizzando un nuovo parametro con nome -uo-. E'' facoltativo ma il protocollo GS4 di ADS (Piacenza) lo richiede necessariamente.');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','CODICEAMMINISTRAZIONE','Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','URL_WS_DIZIONARIO','Inserire qui l''endpoint che indica il web service per fare le chiamate alle funzionalità di recupero dati relativo alle classifiche e uffici');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_TINN','USA_WS_CLASSIFICHE','Se = a 1 indica che le classifiche devono essere recuperate tramite web service messo a disposizione dal protocollo TINN, altrimenti il sistema funzionerà in maniera standard, ossia mappando le varie classifiche direttamente sull''albero degli interventi. Questo parametro è direttamente legato al parametro URL_WS_DIZIONARIO, infatti se si decide di recuperare le classifiche da web service, deve ovviamente essere indicato anche l''end point del web service');
insert into verticalizzazionibase (modulo, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC', 'abilita l''integrazione con il sistema di archiviazione documentale LegalDoc Folders di Infocert');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','DATA_FOLDER_PATH','percorso della cartella locale di LegalDocs dove archiviare i file');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','SERVICE','attributo obbligatorio all''interno del file di avvio che identifica il servizio finale al quale sono indirizzati i file da trasferire tramite LegalDoc Connector. Il contenuto di questo campo è case sensitive e deve corrispondere all''identificativo fornito dal gestore per il servizio prescelto');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','END_USER_ID','attributo facoltativo all''interno del file di avvio che può essere usato per identificare l''utente finale, di norma rappresentato da un cliente del cliente intermediario (es. Banca1, Banca2...); il contenuto di questo campo è libero e, se presente, viene riportato nei messaggi PEC di segnalazione');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','NOME','attributo facoltativo all''interno del file di avvio ad uso del Cliente per descrivere la tipologia di file che costituisce il job; il contenuto di questo campo è libero e, se presente, viene riportato nei messaggi PEC di segnalazione');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','FEEDBACK_EMAIL','attributo facoltativo all''interno del file di avvio che può essere usato per specificare l''indirizzo di PEC a cui inviare l''eventuale notifica di errore del job; se questo campo non è presente, la notifica viene inviata all''indirizzo PEC specificato in fase di registrazione');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','FILE_EXTENSIONS','lista di estensioni di file dichiarate in fase contrattuale. (separate dal carattere '';'')');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','SGD','parametro obbligatorio fornito da InfoCert in fase contrattuale; indica il codice del Sistema di Gestione Documentale (SGD) per il quale si sta effettuando il trasferimento');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','DATA_MAX_CONS','parametro facoltativo per richiedere la conservazione dei dati inviati entro una certa data; la data massima di conservazione richiesta deve essere di almeno tre giorni successiva alla data di invio dei file. La data deve essere espressa nel formato dd-mm-aaaa');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','MAX_NUM_FILES','numero massimo di file per singola archiviazione');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','MAX_NUM_ISTANZE_PER_QUERY','numero massimo di record della tabella ISTANZE da recuperare dalla query che individua le istanze da archiviare');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','MAX_FILE_SIZE','dimensione massima in byte del singolo file');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','MAX_FILE_NAME_LENGTH','lunghezza massima in caratteri del nome del singolo file');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','DALLA_DATA','filtro opzionale applicato alla colonna DATAFINEEFFETTIVA della tabella ISTANZE_TEMPISTICA');
insert into verticalizzazioniparametribase (modulo, parametro, descrizione) values ('ARCHIVIAZIONE_DOC_LEGALDOC','ALLA_DATA','filtro opzionale applicato alla colonna DATAFINEEFFETTIVA della tabella ISTANZE_TEMPISTICA');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_ATTIVO', 'OGGETTO_UPPERCASE', 'Solo se valorizzato a 1, il componente .net Protocollo Manager trasforma la stringa dell''oggetto tutta in maiuscolo, oggetto quindi che viene successivamente inviato al sistema di protocollo in maiuscolo anche se sulla maschera di protocollazione viene scritto in minuscolo');
